    page.evaluate('window.startRun(6400)');page.wait_for_function('window.done===true',timeout=20000);save(E/'trace.json',page.evaluate('window.trace'));video_payload=page.evaluate('window.videoReady');video_bytes=base64.b64decode(video_payload.pop('base64'));assert len(video_bytes)==video_payload['bytes'];(E/'playback.webm').write_bytes(video_bytes);save(E/'video_recorder.json',video_payload);scrubs=[]
