    h=context.new_page();h.on('pageerror',lambda e:errors.append(str(e)));h.goto((E/'history.html').as_uri(),wait_until='load');h.evaluate('document.fonts.ready');decoded_history=h.evaluate("""async()=>await Promise.all([...document.querySelectorAll('image')].map(async n=>{const i=new Image();i.src=n.getAttribute('href');await i.decode();const b=Uint8Array.from(atob(i.src.split(',')[1]),c=>c.charCodeAt(0));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');}))""");assert set(decoded_history)=={sha(paths[k]) for k in ['v1','attack']};h.screenshot(path=str(E/'history.png'));h.close();context.close()
